"""Prepare ten large-cell study sheets, eight references per sheet."""
from pathlib import Path
from collections import Counter
import sys,json
sys.pycache_prefix=str(Path(__file__).resolve().parents[1]/'.work/cache/python')
import _bootstrap
from details_lighting_v43 import CATALOG,GROUPS,LIGHT_BASE,COTTON_BASE,DRESS_BASE
root=_bootstrap.ROOT;es=[e for e in CATALOG if e.get('study_reference')];counts=Counter();prefix=dict(zip(['hands','nose_ear_teeth','skin_details','portrait_lighting','garment_dynamics'],['DH','NF','SD','IL','GD']))
for e in es:counts[e['category']]+=1;e['id']=prefix[e['category']]+f"{counts[e['category']]:03}"
common='''Use case: scientific-educational.
Asset type: original adult female character-art observation reference atlas.
Create a portrait1536x2048 sheet with EXACTLY2 columns by4 rows, eight equal wide cells. Warm ivory page, thin medium-gray straight dividing rules at x50% and y25%,50%,75%. Each cell is one clearly framed study, not a collage of more tiny panels. Precise softly shaded illustration, natural structure and readable edges, polished semi-realistic art-reference style compatible with anime character design. All subjects are original adults age25+, no actor likeness. Keep the entire requested subject, every relevant fingertip, held object, face feature or garment hem/shoe inside its own cell with20px free margins. No diagram arrows or decorative scenery. Only text is the exact cell ID in small readable black type at upper left. No titles, captions, logos or watermark. No medical tools, disease diagnosis charts or exaggerated injuries. Do not invent extra body parts or duplicate objects.
'''
directions={
 'hand_structure':'Eight isolated adult FEMALE hand studies. One complete right hand per cell including short forearm/wrist and all fingertips. EXACTLY one thumb + four other fingers, correctly connected and bending naturally. Palm view thumb is on image LEFT; hand-back view thumb is on image RIGHT. Do not hide extra fingers behind other fingers. Neutral skin, plain short nails, no jewelry, no full person. Emphasize specified differences in proportion, knuckles or palm surface without caricature.',
 'hand_contact':'Eight isolated single adult FEMALE right-hand studies with their listed everyday object. Exactly five anatomically connected digits total. Fingers may naturally occlude behind the object, but roots and visible tips must make sense. Never pass fingers through a cup, phone, book or cloth. One object per cell, no full person, complete wrist/object in frame, normal contact shadow. Keep the grip readable rather than hiding it behind the object.',
 'nose':'Eight adult female NOSE close-ups, brow-base to upper-lip crop, never the whole face. Neutral warm skin and neutral lighting except the small specified view difference. Each named feature must visibly match the recipe. These are variation studies, not before/after beauty changes. No clinical annotations or nostril instruments.',
 'ear':'Eight adult female human EAR close-ups. Complete outer ear, earlobe and root connection in every cell; small surrounding temple/jaw crop, hair tucked away. No earrings, pointed fantasy ears or earphones. Clearly distinguish attached/free lobe and requested inner fold or viewing angle.',
 'teeth':'Eight adult female MOUTH/TEETH close-ups, lower-nose edge to chin only, no full face. Natural restrained smiles or slightly parted lips as requested. Ivory teeth rendered as coherent curved rows with soft boundaries, never rows of equal square blocks or black grid lines. No dentist view, tools, gore, extreme fang rows or exaggerated open mouth.',
 'skin_face':'Eight local adult-skin reference patches at the listed regions. Near-realistic painted detail, intact skin, subtle fine pores/creases/hair enlarged just enough for drawing study. No whole body and no isolated floating wounds. Natural minor variation, no beauty airbrush. Hands/knuckles must retain coherent local anatomy. Each patch fills most of its cell without cropping away the key shape.',
 'skin_body':'Eight local adult-skin reference patches at listed limb/shoulder/heel regions, not whole bodies. Intact natural surface and restrained details, nonmedical. Include enough anatomical context to identify elbow/knee/wrist/shoulder/heel. No cleavage, private areas, medical labels, rulers, severe cracking or lesions.',
 'lighting':'Controlled comparison: ALL EIGHT CELLS MUST show the EXACT SAME original25+ woman, identical head size and absolutely identical FRONTAL head pose, chin-length black bob tucked behind ears, dark-brown eyes, medium-light warm skin, neutral expression, no makeup/jewelry, gray crewneck. Same camera, same crop and simple neutral gray backdrop inside each cell. ONLY change the listed lighting. Match her facial identity and silhouette across all8, do not turn head or change expression to suggest lighting. Make directional shadows physically consistent, not just tint each picture. Framing head to upper shoulders, hair fully inside cell.',
 'cotton':'Controlled garment comparison: same original adult woman with BLACK LOW PONYTAIL in ALL8 cells; exact SAME loose WHITE long-sleeve cotton button shirt TUCKED into BLUE-GRAY STRAIGHT TROUSERS, WHITE FLAT SHOES. No skirts, belts, different jackets or color changes. Same neutral soft lighting and body proportions. Full body including hands and shoes, fixed three-quarter camera as possible. Only listed pose/contact/wind changes. Cloth must compress inside bent joints and pull from support points, not random stripe patterns. Small seated/crouching poses retain believable body scale rather than enlarged heads. Clothing opaque and torso covered in every pose.',
 'dress':'Controlled garment comparison: same original adult woman with BROWN LOW BUN in ALL8 cells; exact SAME opaque MUTED BLUE-GRAY LONG-SLEEVE MIDI DRESS to lower calves, THIN matching waist belt, WHITE FLAT SHOES. Same neckline, sleeve/hem length, fabric and person proportions throughout. Same neutral soft lighting, full body, same three-quarter camera as possible. Only pose/contact/wind changes. No new skirt slits, outfit variants, short skirts, cleavage or transparent clothing. Show hands, fabric contact points and all shoes whenever not naturally covered by skirt in kneeling pose. Wind and turning create directional lag while waist belt remains anchored.'}
jobs=[]
for kind,cid,dim in GROUPS:
    group=[e for e in es if e['study_group']==kind];assert len(group)==8
    prompt=common+directions[kind]+'\nOrdered cells left to right then down:\n'+'\n'.join(f"Cell{i+1}, ID {e['id']}: {e['name']} / {e['en']}. {e['illustration_recipe']}." for i,e in enumerate(group))
    jobs.append(dict(id='details-v43-'+kind,category=cid,dimension=dim,title=dim+' · 8项观察',image=f"images/sheet-{group[0]['id'].lower()}-{group[-1]['id'].lower()}.png",columns=2,rows=4,edition=43,entries=[{k:e[k] for k in ['id','name','en']} for e in group],prompt=prompt))
p=root/'source/image-jobs.json';old=json.loads(p.read_text(encoding='utf-8'));prior={j['id']:j for j in old if j.get('edition')==43}
for j in jobs:
    for f in ['image','edit_prompt','reference_image','edit_history','column_boundaries','row_boundaries']:
        if f in prior.get(j['id'],{}):j[f]=prior[j['id']][f]
    if (root/j['image']).exists() and prior.get(j['id'],{}).get('prompt'):j['prompt']=prior[j['id']]['prompt']
p.write_text(json.dumps([j for j in old if j.get('edition')!=43]+jobs,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
out=root/'.work/verification/details-v43/jobs.json';out.parent.mkdir(parents=True,exist_ok=True);out.write_text(json.dumps(jobs,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print(json.dumps([{'id':j['id'],'cells':len(j['entries'])} for j in jobs]))
